import React from "react";
import data from "../data/data.json";
import images from "../images";
import { IoLogoWhatsapp } from "react-icons/io";

export type ContactBarCertification = {
  label: string;
  href: string;
};

export interface ContactBarProps {
  title: string;
  imageSrc?: string;
  imageAlt?: string;
  ctaLabel: string;
  ctaHref: string;
  certifications?: ContactBarCertification[];
  certificationsTitle?: string;
  phone?: string;
  whatsApp?: string;
  className?: string;
}

const defaultData = data as {
  phone?: string;
  whatsApp?: string;
};

function formatPhone(phone?: string): string {
  if (!phone) {
    return "";
  }
  const cleaned = phone.replace(/\D+/g, "");
  if (cleaned.length === 11 && cleaned.startsWith("1")) {
    return `+1 ${cleaned.slice(1, 4)} ${cleaned.slice(4, 7)} ${cleaned.slice(7)}`;
  }
  return phone;
}

const ContactBar: React.FC<ContactBarProps> = ({
  title,
  imageSrc = images.logo.src,
  imageAlt = "Contact",
  ctaLabel,
  ctaHref,
  certifications = [],
  certificationsTitle = "Certifications:",
  phone = defaultData.phone,
  whatsApp = defaultData.whatsApp,
  className = "",
}) => {
  return (
    <section className={`${styles.section} ${className}`}>
      <div className={styles.inner}>
        <div className={styles.imageWrap}>
          <img src={imageSrc} alt={imageAlt} className={styles.image} />
        </div>

        <div className={styles.content}>
          <h3 className={styles.title}>{title}</h3>
          <p className={styles.description}>
            Tell us what you love, where you want to go, and we’ll craft a one-of-a-kind, tailor-made journey you’ll never forget.
          </p>

          <div className={styles.contactLinks}>
            {phone ? (
              <a href={`tel:${phone}`} className={styles.link}>
                {formatPhone(phone)}
              </a>
            ) : null}
            {whatsApp ? (
              <>
                <a href={whatsApp} className={`${styles.link} rounded-full p-1 bg-contrast`}>
                  <IoLogoWhatsapp className="text-[#25D366] text-3xl " /> 
                </a>
              </>
            ) : null}
          </div>

          {certifications.length > 0 ? (
            <div className={styles.certifications}>
              <span className={styles.certificationsTitle}>{certificationsTitle}</span>
              <div className={styles.certificationsLinks}>
                {certifications.map((certification) => (
                  <a
                    key={`${certification.label}-${certification.href}`}
                    href={certification.href}
                    target="_blank"
                    rel="noreferrer"
                    className={styles.certificationLink}
                  >
                    {certification.label}
                  </a>
                ))}
              </div>
            </div>
          ) : null}
        </div>

        <figure>
          <img className={styles.jennyImage} src={images.jenny.src} alt={images.jenny.alt} />
        </figure>
        <a href={ctaHref} className={styles.cta}>
          {ctaLabel}
        </a>
      </div>
    </section>
  );
};

export default ContactBar;

const styles = {
  section: "w-full bg-secondary text-contrast shadow-xl",
  content: "flex flex-col gap-2 text-center md:text-left w-1/2",
  inner: "flex flex-col sm:flex-row justify-between mx-auto w-full max-w-[1400px] px-4 py-5 sm:px-8 sm:py-6 gap-4 items-center",
  imageWrap: "flex justify-center md:justify-start",
  image: "h-40 w-40  object-cover",
  title: "h1_desk text-contrast",
  contactLinks: "flex flex-wrap gap-x-4 gap-y-1 justify-center md:justify-start",
  link: "suptext_desk text-contrast hover:text-main transition-colors duration-200 flex items-center",
  certifications: "flex flex-col gap-1",
  certificationsTitle: "subtext_desk text-contrast/90 uppercase tracking-wide",
  certificationsLinks: "flex flex-wrap gap-2 justify-center md:justify-start",
  certificationLink:
    "subtext_desk text-contrast border border-contrast/40 px-2 py-1 hover:bg-contrast/10 transition-colors duration-200",
  cta:
    "menu_desk inline-flex justify-center items-center rounded-full bg-terciary px-6 py-3 text-contrast font-semibold whitespace-nowrap hover:bg-contrast transition-colors duration-200",
  jennyImage: "w-44 h-44 rounded-full object-cover border-2 border-contrast/40",
  description: ""
};
